package com.ecommerce.service;
import com.ecommerce.dto.*; import com.ecommerce.entity.*; import com.ecommerce.exception.*; import com.ecommerce.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class CarritoService { private final CarritoRepository carritos;private final ProductoRepository productos;private final UsuarioRepository usuarios; public CarritoService(CarritoRepository c,ProductoRepository p,UsuarioRepository u){carritos=c;productos=p;usuarios=u;}
 @Transactional public CarritoResponse obtenerCarrito(String email){return map(carrito(user(email)));}
 @Transactional public CarritoResponse agregarItem(String email,CarritoItemRequest r){Carrito c=carrito(user(email));Producto p=productos.findById(r.getProductoId()).orElseThrow(()->new ResourceNotFoundException("Producto no encontrado"));DetalleCarrito found=c.getDetalles().stream().filter(d->d.getProducto().getId().equals(p.getId())).findFirst().orElse(null);int finalQty=(found==null?0:found.getCantidad())+r.getCantidad();if(finalQty>p.getStock())throw new BadRequestException("Stock insuficiente. Disponible: "+p.getStock());if(found!=null)found.setCantidad(finalQty);else{DetalleCarrito d=new DetalleCarrito();d.setCarrito(c);d.setProducto(p);d.setCantidad(r.getCantidad());d.setPrecioUnitario(p.getPrecio());c.getDetalles().add(d);}return map(carritos.save(c));}
 @Transactional public CarritoResponse actualizarCantidad(String email,Long id,ActualizarCantidadRequest r){Carrito c=carrito(user(email));DetalleCarrito d=c.getDetalles().stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->new ResourceNotFoundException("Detalle no encontrado"));if(r.getCantidad()>d.getProducto().getStock())throw new BadRequestException("Stock insuficiente. Disponible: "+d.getProducto().getStock());d.setCantidad(r.getCantidad());return map(carritos.save(c));}
 @Transactional public CarritoResponse eliminarItem(String email,Long id){Carrito c=carrito(user(email));boolean ok=c.getDetalles().removeIf(d->d.getId().equals(id));if(!ok)throw new ResourceNotFoundException("Detalle no encontrado");return map(carritos.save(c));}
 @Transactional public CarritoResponse vaciarCarrito(String email){Carrito c=carrito(user(email));c.getDetalles().clear();return map(carritos.save(c));}
 private Usuario user(String e){return usuarios.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("Usuario no encontrado"));}
 private Carrito carrito(Usuario u){return carritos.findByUsuarioId(u.getId()).orElseGet(()->{Carrito c=new Carrito();c.setUsuario(u);return carritos.save(c);});}
 private CarritoResponse map(Carrito c){List<CarritoItemResponse> items=new ArrayList<>();BigDecimal total=BigDecimal.ZERO;int count=0;for(DetalleCarrito d:c.getDetalles()){CarritoItemResponse i=new CarritoItemResponse();i.setDetalleId(d.getId());i.setProductoId(d.getProducto().getId());i.setProductoNombre(d.getProducto().getNombre());i.setImagenUrl(d.getProducto().getImagenUrl());i.setCantidad(d.getCantidad());i.setPrecioUnitario(d.getPrecioUnitario());i.setSubtotal(d.getPrecioUnitario().multiply(BigDecimal.valueOf(d.getCantidad())));total=total.add(i.getSubtotal());count+=d.getCantidad();items.add(i);}CarritoResponse r=new CarritoResponse();r.setCarritoId(c.getId());r.setItems(items);r.setTotal(total);r.setTotalItems(count);return r;} }
